/home/luke/projects/buzzdetect/engine/.venv/bin/python3 05_distill/bench_arch.py time --seconds 20 --out /home/luke/projects/buzzdetect-training/05_distill/data/_shared/arch_mm --candidates floor fe@fast32h16 fe@fast32h16+mmt fe@fast32h32+mmt fe@fast32+mmt fe@twofast32+mmt fe@yamnet+conv fe@yamnet+mmt a0.25@fast32h16 a0.25@fast32h16+mmt a0.25_d8_f2@fast32h16+mmt a0.375@fast32h16+mmt a0.50_d8@fast32h16+mmt a0.50@fast32h16+mmt a0.75_d8@fast32h16+mmt a0.50@twofast32+mmt a0.50_d6@fast32+mmt a0.50_d8@fast32 a0.50_d8@fast32+mmt a0.50_d10@fast32+mmt a0.50_d12@fast32+mmt a0.375@fast32+mmt a0.50@fast32+mmt a0.25@yamnet+mmt a0.25_d8@yamnet+conv a0.25_d8@yamnet+mmt a0.375_d8@yamnet+mmt a0.50_d8@yamnet+conv a0.50_d8@yamnet+mmt a0.50@yamnet+mmt a0.75_d8@yamnet+mmt a1.00@yamnet+mmt
